# owner: platform
"""Plain text contact rows for substitute teachers."""

from typing import List, Tuple
from rosterkit.models import Student

def sort_key(student: Student) -> Tuple[str, str]:
    """Order by last name, then first name."""
    return (student.last_name, student.first_name)

def vet_contacts(students: List[Student]) -> List[Student]:
    if not students:
        raise ValueError("no students given")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email for {name}")
    return students

def format_contact(
    student: Student, widths: Tuple[int, int]
) -> str:
    """One text row: name, section, then email."""
    name = student.display_name.ljust(widths[0])
    section = student.section.ljust(widths[1])
    return f"{name}  {section}  {student.email}"

def contact_rows(students: List[Student]) -> List[str]:
    """One aligned text row per student, sorted by name."""
    people = sorted(vet_contacts(students), key=sort_key)
    widths = (
        max(len(item.display_name) for item in people),
        max(len(item.section) for item in people)
    )
    return [format_contact(item, widths) for item in people]
